"""Dilution of precision (DOP) from satellite geometry.

A receiver solves for 4 unknowns: position (x, y, z) and clock bias. Linearizing
the range equations gives one row per satellite in the geometry matrix G:
    [-ex, -ey, -ez, 1]
where e is the unit vector from receiver to satellite. Errors in the solution
scale with the covariance-like matrix Q = (G^T G)^-1, and
    GDOP = sqrt(trace Q)
    PDOP = sqrt(Q11 + Q22 + Q33)          (3-D position)
    TDOP = sqrt(Q44)                      (clock)
    HDOP, VDOP: the same position block of Q, rotated to local East-North-Up,
                HDOP = sqrt(Q_EE + Q_NN),  VDOP = sqrt(Q_UU).
"""

import numpy as np

KEYS = ("gdop", "pdop", "hdop", "vdop", "tdop")
MAX_COND = 1e12  # G^T G worse than this is treated as singular (no solution)


def _undefined():
    return {k: float("nan") for k in KEYS}


def dop_batch(unit_los, visible, enu):
    """DOP for many receivers at once (Monte Carlo trials).

    unit_los: (M, N, 3) unit vectors to all N satellites for each of M trials
    visible : (M, N) bool, which satellites count in each trial
    enu     : (M, 3, 3) local East-North-Up matrices
    Returns a dict of (M,) arrays (same keys as dop()), NaN where undefined.

    Same maths as dop(), but with no ragged arrays: the sum over visible
    satellites G^T G = sum_i g_i g_i^T is taken with weight 1 (visible) or 0.
    """
    M = unit_los.shape[0]
    g = np.concatenate([-unit_los, np.ones(unit_los.shape[:-1] + (1,))], axis=-1)   # (M, N, 4)
    GtG = np.einsum("ms,msi,msj->mij", visible.astype(float), g, g)                 # (M, 4, 4)

    ok = visible.sum(axis=1) >= 4
    eye = np.eye(4)
    with np.errstate(divide="ignore", invalid="ignore"):
        cond = np.linalg.cond(np.where(ok[:, None, None], GtG, eye))
    ok &= np.isfinite(cond) & (cond <= MAX_COND)

    Q = np.linalg.inv(np.where(ok[:, None, None], GtG, eye))                        # identity where undefined
    Q_enu = enu @ Q[:, :3, :3] @ np.swapaxes(enu, 1, 2)

    def pick(values):
        return np.where(ok, np.sqrt(values), np.nan)

    return {
        "gdop": pick(np.trace(Q, axis1=1, axis2=2)),
        "pdop": pick(Q[:, 0, 0] + Q[:, 1, 1] + Q[:, 2, 2]),
        "hdop": pick(Q_enu[:, 0, 0] + Q_enu[:, 1, 1]),
        "vdop": pick(Q_enu[:, 2, 2]),
        "tdop": pick(Q[:, 3, 3]),
    }


def dop(unit_los, enu, estimate_clock=True):
    """DOP values from unit line-of-sight vectors (N x 3) and the ENU matrix (3 x 3).

    Returns a dict with gdop, pdop, hdop, vdop, tdop. If too few satellites are given
    (4, or 3 when the clock is known) or the geometry is singular, every value is NaN.

    estimate_clock=False: the receiver clock is assumed known, so only x, y, z are solved
    for (rows [-ex, -ey, -ez]); GDOP and TDOP are then not defined (NaN). Langley (1999)
    uses this case to show how much the clock unknown costs in the vertical.
    """
    unit_los = np.asarray(unit_los, dtype=float).reshape(-1, 3)
    if len(unit_los) < (4 if estimate_clock else 3):
        return _undefined()

    G = np.hstack([-unit_los, np.ones((len(unit_los), 1))]) if estimate_clock else -unit_los
    GtG = G.T @ G
    if not np.isfinite(np.linalg.cond(GtG)) or np.linalg.cond(GtG) > MAX_COND:
        return _undefined()

    Q = np.linalg.inv(GtG)
    Q_enu = enu @ Q[:3, :3] @ enu.T  # position block expressed in East, North, Up

    return {
        "gdop": float(np.sqrt(np.trace(Q))) if estimate_clock else float("nan"),
        "pdop": float(np.sqrt(np.trace(Q[:3, :3]))),
        "hdop": float(np.sqrt(Q_enu[0, 0] + Q_enu[1, 1])),
        "vdop": float(np.sqrt(Q_enu[2, 2])),
        "tdop": float(np.sqrt(Q[3, 3])) if estimate_clock else float("nan"),
    }
"""Satellite orbits: orbital elements, Kepler's equation, positions, and derived quantities.

Model: two-body Kepler motion on circular or elliptical orbits (no perturbations).
Frame: the inertial frame, origin at Earth's centre, +z through the north pole. The
Earth rotates in this frame (see geometry.py); at t = 0 longitude 0 points along +x
and longitude 90E along +y. Units: km, seconds, degrees (angles in the tables).
"""

import numpy as np

from . import geometry

MU = 398600.4418       # Earth's gravitational parameter, km^3/s^2
A_GPS = 26559.7        # nominal GPS orbit radius (semi-major axis), km
INC_GPS = 55.0         # nominal GPS inclination, degrees

MAX_ECC = 0.9                  # largest eccentricity accepted
MIN_PERIGEE_ALT_KM = 160.0     # lowest perigee accepted (below this, drag would pull it down fast)
MAX_APOGEE_RADIUS_KM = 500000.0  # farthest apogee accepted (beyond the Moon's orbit, two-body motion is not meaningful)
LCM_TOL = 0.03                 # cycles: how close to a whole number of orbits counts as "repeated"
LCM_MAX_DAYS = 3650            # longest common period searched (10 years)

# An "elements" table has one row per satellite and these columns (angles in degrees):
A, ECC, INC, RAAN, ARGP, M0 = range(6)
#   A    semi-major axis (km)                    ECC   eccentricity (0 = circle)
#   INC  inclination                             RAAN  right ascension of the ascending node
#   ARGP argument of perigee                     M0    mean anomaly at t = 0
# (The ascending node is where the orbit crosses the equator going north; RAAN is its angle
# from +x. Perigee is the closest point to Earth; the mean anomaly grows steadily in time
# and is 0 at perigee.)


def make_elements(a, ecc=0.0, inc_deg=0.0, raan_deg=0.0, argp_deg=0.0, m0_deg=0.0):
    """Elements table (rows x 6) from numbers or arrays (broadcast against each other)."""
    cols = np.broadcast_arrays(*[np.asarray(x, dtype=float) for x in (a, ecc, inc_deg, raan_deg, argp_deg, m0_deg)])
    return np.stack(cols, axis=-1).reshape(-1, 6)


def walker(T=24, P=6, F=1, a=A_GPS, inc_deg=INC_GPS):
    """Walker delta pattern T/P/F: T satellites in P equally spaced circular planes.

    Plane p has RAAN = 360*p/P. Satellites inside a plane are spaced 360/(T/P)
    apart. Neighbouring planes are shifted along the orbit by F*360/T.
    Walker 24/6/1 is the idealized nominal GPS constellation.
    """
    per_plane = T // P
    raan = np.repeat(360.0 * np.arange(P) / P, per_plane)
    slot = np.tile(np.arange(per_plane), P)
    plane = np.repeat(np.arange(P), per_plane)
    m0 = (360.0 * slot / per_plane + 360.0 * F * plane / T) % 360.0
    return make_elements(a, 0.0, inc_deg, raan, 0.0, m0)


def names(T=24, P=6):
    """Labels like A1..A4, B1..B4, ... (letter = plane, number = slot in plane)."""
    per_plane = T // P
    return [f"{chr(ord('A') + p)}{s + 1}" for p in range(P) for s in range(per_plane)]


def geostationary_radius():
    """Orbit radius (km) whose period equals one sidereal day: a = (mu * (T/2pi)^2)^(1/3).
    A circular equatorial orbit of this size turns with the Earth, so it hangs over one
    spot (geostationary)."""
    return (MU * (geometry.T_SIDEREAL / (2.0 * np.pi)) ** 2) ** (1.0 / 3.0)


def geostationary(lon_deg):
    """One geostationary satellite above longitude lon_deg (east). At t = 0 the inertial angle of
    that longitude is lon + (the Earth's angle at the epoch), so that is the phase at t = 0."""
    return make_elements(geostationary_radius(), 0.0, 0.0, 0.0, 0.0, (lon_deg + geometry.EARTH_ANGLE_AT_EPOCH) % 360.0)


def validate_orbit(a, ecc=0.0, inc_deg=0.0):
