    }
    if (hold !== 0) {
      const held = (now - holdStart) / 1000;
      const rate = Math.min(HOLD_START_RATE * 2 ** held, HOLD_MAX_RATE);    // simulated seconds per real second
      t += hold * rate * dt;
      dirty = true;
    }
    if (dirty) { dirty = false; refresh(); }
  }
